Hashing is an improvement technique over the Direct Access Table. The idea is to use a hash function that converts a given number or any other key to a smaller number and uses the small number as the index in a table called a hash table. Quadratic Probing:Quadratic probing is an open-addressing scheme where we look for the i2'th slot in the i'th iteration if the given hash value x collides in the hash table. We have already discussed linear probing implementation.How Quadratic Probing is done? Let hash(x) be the slot index computed using the hash function.If the slot hash(x) % S is full, then we try (hash(x) + 1*1) % S.If (hash(x) + 1*1) % S is also full, then we try (hash(x) + 2*2) % S.If (hash(x) + 2*2) % S is also full, then we try (hash(x) + 3*3) % S.This process is repeated for all the values of i until an empty slot is found.Example: Let us consider a simple hash function as “key mod 7” and  sequence of keys as 22, 30 and 50.Below is the implementation of the above approach:Try It Yourself
            C++

    #include <iostream>
#include <vector>
using namespace std;

void quadProbing(vector<int>& table, int tsize, vector<int>& arr) {
    int n = arr.size();

    for (int i = 0; i < n; i++) {
        // Hash function
        int hv = arr[i] % tsize;

        if (table[hv] == -1) {
            // Place directly if slot is empty
            table[hv] = arr[i] ;
        }
        else {
            // Quadratic probing in case of collision
            for (int j = 1; j <= tsize; j++) {
                // Compute new index using quadratic probing
                int t = (hv + j * j) % tsize;

                // Place element if new slot is empty
                if (table[t] == -1) {
                    table[t] = arr[i];
                    break;
                }
            }
        }
    }
}

int main() {
    vector<int> arr = { 50, 700, 76, 85, 92, 73, 101 };

    int tsize = 11 ;

    vector<int> table(tsize, -1) ;

    quadProbing(table, tsize, arr) ;

    for (int i = 0; i < table.size(); i++) {
        cout << table[i] << " ";
    }

    return 0;
}


