Output73 -1 101 -1 92 -1 50 700 85 -1 76 Time Complexity: O(n * l), where n is the length of the array and l is the size of the hash table.Auxiliary Space: O(1)The above implementation of quadratic probing does not guarantee that we will always be able to use a hash table empty slot. It might happen that some entries do not get a slot even if there is a slot available. Let's consider the input array [21, 10, 32, 43, 54, 65, 87, 76] and table size 11, we get the output as [10, -1, 65, 32, 54, -1, -1, -1, 43, -1, 21] which means the items 87 and 76 never get a slot.  To make sure that elements get filled, we need to have a higher table size. A hash table can be fully utilized using the below idea.Iterate over the hash table to next power of 2 of table size. For example if table size is 11, then iterate 16 times.  And iterate over the hash table using the below formula hash(x) =  [hash(x)  + (j + j*j)/2] % (Next power of 2 of table size)
            C++

    #include <iostream>
#include <vector>
using namespace std;

// Function to compute the next 
// power of 2 greater than or equal to m
int nextPowerOf2(int m) {
    m-- ;
    m |= m >> 1 ;
    m |= m >> 2 ;
    m |= m >> 4 ;
    m |= m >> 8 ;
    m |= m >> 16 ;
    m |= m >> 32 ;
    m++ ;
    return m ;
}

void quadProbing(vector<int>& table, int tsize, vector<int>& arr) {

    // Get number of elements to insert
    int n = arr.size();

    for (int i = 0; i < n; i++) {

        // Hash function
        int hv = arr[i] % tsize;

        // Place directly if slot is empty
        if (table[hv] == -1) {
            table[hv] = arr[i];
        }
        else {
            int m = nextPowerOf2(tsize) ;

            // Perform modified quadratic probing
            for (int j = 1; j <= m; j++) {

                // Compute new index using the
                // custom probing formula
                int t = (hv + (j + j * j) / 2) % m;

                // Skip if out of bounds for original table size
                if (t >= tsize)
                    continue ;

                // Place element if slot is empty
                if (table[t] == -1) {
                    table[t] = arr[i];
                    break ;
                }
            }
        }
    }
}

int main() {
    vector<int> arr = { 21, 10, 32, 43, 54, 65, 87, 76 };
    int tsize = 11;
    vector<int> table(tsize, -1);
    quadProbing(table, tsize, arr);

    for (int i = 0; i < table.size(); i++) {
        cout << table[i] << " ";
    }
    cout << endl;

    return 0;
}


